  q = mix(q, uKhop.xy + xoay(q - uKhop.xy, uKhop.z) + uLech.xy, w.g);
  // thân trên: xoay quanh hông (chân neo) + lệch lò xo
  q = uHong.xy + xoay(q - uHong.xy, uHong.z * tren) + uLech.zw * tren;
